#include <bits/stdc++.h>
using namespace std;

int main() {
    long long a, b;
    if (!(cin >> a >> b)) return 0;

    long long cnt = 1;
    vector<long long> ans;
    ans.push_back(b);
    bool flag = true;

    while (b > a) {
        long long r = b % 10;
        if (r % 2 == 0) {
            b /= 2;
            cnt += 1;
            ans.push_back(b);
        } else {
            if (b % 10 % 2 != 0 && b % 10 != 1) {
                flag = false;
                break;
            } else {
                b /= 10;
                ans.push_back(b);
                cnt += 1;
            }
        }
    }

    if (flag && a == b) {
        cout << "YES\n";
        cout << cnt << "\n";
        reverse(ans.begin(), ans.end());
        for (size_t i = 0; i < ans.size(); ++i) {
            if (i) cout << ' ';
            cout << ans[i];
        }
        cout << "\n";
    } else {
        cout << "NO\n";
    }

    return 0;
}

